#!/usr/bin/env python3
"""Build a self-contained review page; status comes from explicit evidence files."""
import argparse,base64,json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
parser=argparse.ArgumentParser();parser.add_argument('--output',type=Path,default=ROOT/'review.html');parser.add_argument('--drafts',type=Path);parser.add_argument('--trials',type=Path);parser.add_argument('--apps-evidence',type=Path);args=parser.parse_args()
rows=json.loads((ROOT/'catalog/coverage.json').read_text())['services'];listings=json.loads((ROOT/'listings.json').read_text());starters=json.loads((ROOT/'examples/catalog/starter-flows.json').read_text());drafts=json.loads(args.drafts.read_text()) if args.drafts and args.drafts.exists() else {};apps=[json.loads(p.read_text()) for p in (ROOT/'apps').glob('*.json')]
trial_data=json.loads(args.trials.read_text()).get('services',[]) if args.trials and args.trials.exists() else []
trial_map={x['service']:x for x in trial_data}
for r in rows:
 r['trial']=trial_map.get(r['key'])
 if drafts.get(r['key'],{}).get('operation_names_synced'):
  r['blockers']=[x.replace('Expanded tool set requires Coze import verification and authorized real trials.','Coze tool names and counts verified. Full parameter parity and expanded Coze runtime trials remain unverified.') for x in r['blockers']]
 r['icon_data']='data:image/png;base64,'+base64.b64encode((ROOT/r['icon']).read_bytes()).decode();r['listing']=listings.get(r['key']);r['starter']=starters.get(r['key']);r['draft']=drafts.get(r['key'])
 r['search_aliases']={'localization':'翻译 本地化','shorturl':'短链 短网址','serp':'谷歌 搜索','kling':'可灵 视频','hailuo':'海螺 视频','seedance':'豆包 视频','seedream':'即梦 豆包 图片','dreamina':'即梦 数字人','digitalhuman':'数字人','wan':'通义万相 视频','qwen-image':'千问 图片','identity':'身份认证 实名 银行卡 手机号','fish':'语音 合成','glm':'智谱','deepseek':'深度求索'}.get(r['key'],'')
app_evidence=json.loads(args.apps_evidence.read_text()) if args.apps_evidence and args.apps_evidence.exists() else {}
for a in apps:a['draft']=app_evidence.get(a['id']);a['icon_data']='data:image/png;base64,'+base64.b64encode((ROOT/a['icon']).read_bytes()).decode()
payload=json.dumps({'services':rows,'apps':apps},ensure_ascii=False).replace('</','<\\/')
html='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AceDataCloud · Coze 全目录上线审查</title><style>
:root{--ink:#182b43;--muted:#61748b;--line:#dde5ef;--blue:#176cc5;--bg:#f3f6fa}*{box-sizing:border-box}body{margin:0;font-family:Inter,-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC",sans-serif;color:var(--ink);background:var(--bg);line-height:1.6}button,input,select{font:inherit}button,a{touch-action:manipulation}a{color:var(--blue)}.wrap{max-width:1360px;margin:auto;padding:28px 36px}header{background:#112a47;color:white;padding:44px 0 34px}.eyebrow{font-size:13px;letter-spacing:2px;color:#84d8e5}h1{font-size:36px;line-height:1.25;letter-spacing:-1px;margin:14px 0}header p{max-width:940px;color:#cbd9e9;font-size:16px;margin:12px 0}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:18px;margin-top:30px}.stat{border-top:1px solid #4b627a;padding:12px 0}.stat strong{font-size:30px;display:block}.stat span{font-size:13px;color:#b8cde0}.notice{background:#fff5dc;border:1px solid #e8d5a6;border-radius:12px;padding:18px 22px;margin:24px 0}.notice strong{display:block;margin-bottom:4px}.notice p{margin:0;color:#665536}.toolbar{display:flex;align-items:center;flex-wrap:wrap;gap:12px;padding:16px 0;position:sticky;top:0;z-index:2;background:var(--bg)}input,select{border:1px solid #c8d4e1;border-radius:9px;background:#fff;padding:10px 14px;color:var(--ink)}input{flex:1;min-width:240px}button{cursor:pointer;border:1px solid #c8d4e1;border-radius:9px;background:white;padding:10px 15px;color:var(--ink)}button.active{color:white;background:#173e66;border-color:#173e66}.count{font-size:13px;color:var(--muted);margin-bottom:16px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.card{background:white;border:1px solid var(--line);border-radius:16px;padding:21px;display:flex;flex-direction:column;gap:13px;overflow:hidden}.cardhead{display:flex;gap:15px;align-items:center;min-height:75px}.icon{width:72px;height:72px;border-radius:15px;flex-shrink:0}.card h2{font-size:17px;line-height:1.4;margin:0;overflow-wrap:anywhere}.meta{font-size:12px;color:var(--muted);margin-top:4px}.card p{font-size:14px;color:#485d76;margin:0}.badges{display:flex;gap:7px;flex-wrap:wrap}.badge{font-size:11px;padding:3px 8px;background:#edf3fa;color:#365979;border-radius:6px}.badge.warn{background:#fff2d7;color:#806122}.badge.good{background:#e1f3ef;color:#18644f}.card .links{margin-top:auto;display:flex;gap:18px;align-items:center;font-size:13px}.card .links button{padding:6px 12px;border-color:#b9cde1;color:#195e99}.sectionlabel{margin:32px 0 14px;font-size:24px}.subtle{color:var(--muted);font-size:14px}.appgrid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.app{border:1px solid var(--line);background:white;border-radius:14px;padding:20px}.app img{width:50px;height:50px;border-radius:10px;float:left;margin:0 14px 12px 0}.app h3{margin:0;font-size:17px}.app p{font-size:13px;color:var(--muted)}.app button{font-size:13px}.hidden{display:none!important}dialog{max-width:960px;width:calc(100% - 40px);max-height:90vh;border:0;border-radius:18px;padding:0;box-shadow:0 20px 100px #0c223650}dialog::backdrop{background:#10253d9c}.detailtop{position:sticky;top:0;display:flex;gap:18px;align-items:center;padding:24px 28px;background:white;border-bottom:1px solid var(--line);z-index:1}.detailtop h2{margin:0;font-size:23px;overflow-wrap:anywhere}.close{margin-left:auto}.detailbody{padding:8px 28px 30px}.detailbody h3{margin:22px 0 8px;font-size:16px}.detailbody p{white-space:pre-wrap}.detailbody ul{padding-left:22px}.detailbody li{margin:6px 0}pre{white-space:pre-wrap;word-break:break-word;background:#edf2f7;border-radius:10px;padding:18px;font-size:12px;max-height:350px;overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px}td,th{text-align:left;padding:10px 8px;border-bottom:1px solid var(--line);vertical-align:top;overflow-wrap:anywhere}.resultmedia{max-width:100%;max-height:420px;display:block;margin:12px auto;border-radius:12px}audio{width:100%;margin:12px 0}.footer{padding:35px 0;color:var(--muted);font-size:12px}.two{display:grid;grid-template-columns:1fr 1fr;gap:20px}.method{white-space:nowrap;color:#456f8e}.statusnote{border-left:3px solid #edbe51;background:#fff8e8;padding:13px 17px;font-size:14px} @media(max-width:1000px){.grid,.appgrid{grid-template-columns:repeat(2,1fr)}.wrap{padding:24px}.stats{gap:10px}.stat strong{font-size:26px}}@media(max-width:650px){.grid,.appgrid,.two{grid-template-columns:1fr}.stats{grid-template-columns:repeat(3,1fr)}h1{font-size:28px}.wrap{padding:18px}.toolbar{position:static}.detailtop{padding:16px}.detailbody{padding:8px 18px}.icon{width:60px;height:60px}.detailtop h2{font-size:17px}}
</style><header><div class="wrap"><div class="eyebrow">ACE DATA CLOUD × COZE · PRE-LAUNCH REVIEW</div><h1>完整服务目录，上线前逐项审查</h1><p>从用户想完成的任务出发，覆盖 API 插件、场景应用、数据集、开发工具与部署服务。每项都可以查看名字、图标、文案、接口范围和验证状态。</p><div class="stats"><div class="stat"><strong>83</strong><span>公开服务 · 全部建档</span></div><div class="stat"><strong>35</strong><span>API 服务上架文案</span></div><div class="stat"><strong>35 / 113</strong><span>插件定义 / 工具</span></div><div class="stat"><strong>48</strong><span>数据集与其他服务入口</span></div><div class="stat"><strong>9</strong><span>场景 Agent 草稿</span></div></div></div></header><main class="wrap"><div class="notice"><strong>审查状态：材料齐备，执行仍有阻塞；尚未提交 Coze 商店</strong><p>名称与图标可整体审查。定义与素材已覆盖全目录。Coze 已建立 35 个插件项目和 9 个 Agent 草稿；工具名称与数量已核对，目录导航已绑定 83 项服务知识。未发布插件暂不能绑定 Agent，Coze 内完整运行仍待验证。Claude / OpenAI 的复杂输入存在兼容范围限制，详见各项。初始四项中，Flux 曾在本次 review 暂停要求前发布到工作区 v1.0.0，未提交商店；其他项目不会在你审查前发布。</p></div><div class="toolbar"><input id="search" aria-label="搜索服务" placeholder="搜索名字、用途或接口，例如 Suno / Dataset / 翻译"><select id="type" aria-label="按服务类型筛选"><option value="">全部类型</option><option>Api</option><option>Dataset</option><option>Agent</option><option>Deployment</option></select><button id="all" class="active">全部服务</button><button id="needs">需要进一步验证</button><button id="export-review">导出审查意见</button></div><div class="count" id="count"></div><div class="grid" id="grid"></div><h2 class="sectionlabel">用户直接使用的场景应用</h2><p class="subtle">9 个实际 Agent 草稿已保存名称、图标、开场白、示例提问和提示词。服务导航已绑定目录知识；其他 Agent 的工具绑定需要先完成插件工作区发布，目前遵守 review 暂停要求。</p><div class="appgrid" id="apps"></div><h2 class="sectionlabel">上线判断依据</h2><div class="two"><div class="app"><h3>已完成的真实证据</h3><p>初始四项已有真实 Coze 调用：Google 搜索、短链创建与跳转、Seedream 生成、Flux 生成与编辑。六次请求共计 0.846 Credits（包含一次已修复的 Flux 参数错误）。服务导航 Agent 另已在 Coze 完成数据集检索测试：1.7 秒、910 tokens，返回正确服务链接。该测试凭证已停用。全量版本新增的工具不能沿用这些结果冒充通过。</p></div><div class="app"><h3>还需完成的工作</h3><p>完成 Coze 私有凭证连接、插件发布后的 Agent 工具绑定和运行验证；Coze 已确认支持 MCP 与标准 OAuth，但专用客户端、回调和 PKCE 兼容性尚未验证，一键授权尚未完成。导入数量不等于全部参数和所有调用都已通过。23 项新增 API 用例中，18 项已返回完整文本或可访问输出；Hailuo、Luma、本地化调用失败；Wan、Maestro 成品链接不可访问。实测消耗 26.81514 Credits，按最高名义包价约 $4.69，凭证已提前停用。其余问题逐项列在详情里。身份信息、验证码、声音克隆、部署消息发送需要独立测试条件。DeepSeek 使用公开的 AI Dialogue 接口；实时和二进制接口需要兼容方案。</p></div></div><div class="footer">公开目录快照：2026-10-05 · 全部条目都有来源链接 · 未承诺未验证的价格、授权方式、许可证或可用性 · 正式发布必须等待用户 review。</div></main><dialog id="detail"><div class="detailtop" id="detailtop"></div><div class="detailbody" id="detailbody"></div></dialog><script>
const data=PAYLOAD;const $=x=>document.getElementById(x);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const trialStatus={verified_text_response:'API 完整文本已验证',verified_extraction:'API 提取内容已验证',media_url_verified:'API 成品链接已验证',media_url_needs_check:'成品链接待排查',failed:'真实调用失败 · 暂缓上线',incomplete_text_response:'回答截断 · 待修正',pending_or_no_usable_result:'生成未完成 / 暂无可用结果'};const kind={Api:'API 插件',Dataset:'数据集',Agent:'开发工具',Deployment:'部署服务'};let onlyNeeds=false;
function render(){const q=$('search').value.toLowerCase(),t=$('type').value;const rows=data.services.filter(r=>(!t||r.service_type===t)&&(!q||JSON.stringify([r.name,r.title,r.description,r.key,r.operations,r.search_aliases,kind[r.service_type]]).toLowerCase().includes(q))&&(!onlyNeeds||r.service_type==='Api'));$('count').textContent=`显示 ${rows.length} / 83 项服务。点击「查看审查详情」展开上架文案、示例请求与接口清单。`;$('grid').innerHTML=rows.map(r=>`<article class="card"><div class="cardhead"><img class="icon" src="${r.icon_data}" alt="${esc(r.name)} icon"><div><h2>${esc(r.name||r.title)}</h2><div class="meta">${kind[r.service_type]} · ${esc(r.title)}</div></div></div><div class="badges"><span class="badge">${r.tool_count?`${r.tool_count} 个工具`:'目录与使用指引'}</span><span class="badge ${r.draft&&r.draft.tools_imported!==false&&r.draft.expanded_tools_imported!==false?'good':'warn'}">${r.draft?(r.draft.tools_imported===false?'仅项目信息已保存':r.draft.expanded_tools_imported===false?'已有初始版，待补齐':'Coze 草稿已保存'):r.plugin_url?'已有初始版本，待补齐':r.service_type==='Api'?'待导入 / 验证':'已准备入口内容'}</span>${r.key==='deepseek'?'<span class="badge">公开 AI Dialogue 接口</span>':''}</div><p>${esc(r.brief||r.description)}</p>${r.trial?`<div class="badge ${r.trial.status.startsWith('verified')||r.trial.status==='media_url_verified'?'good':'warn'}">${esc(trialStatus[r.trial.status]||r.trial.status)}</div>`:''}<div class="links"><button data-detail="${esc(r.key)}">查看审查详情</button><a href="${esc(r.source_url)}" target="_blank" rel="noreferrer">来源 ↗</a></div></article>`).join('');document.querySelectorAll('[data-detail]').forEach(b=>b.onclick=()=>detail(b.dataset.detail));}
let activeReviewKey='';let decisions={};try{decisions=JSON.parse(localStorage.getItem('acedata-coze-review-20261005')||'{}')}catch(e){}
function reviewForm(key){activeReviewKey=key;const d=decisions[key]||{};return `<h3>我的审查意见</h3><p class="subtle">只保存在此浏览器；不会触发发布。完成后可导出意见文件。</p><select id="review-choice"><option value="pending">待审查</option><option value="keep">保留当前设计</option><option value="change">需要修改</option><option value="hold">暂缓上线</option></select><textarea id="review-note" placeholder="名称、图标、文案或功能的修改意见" style="display:block;width:100%;min-height:90px;margin-top:12px;padding:12px;border:1px solid #c8d4e1;border-radius:9px">${esc(d.note||'')}</textarea><button onclick="saveDecision()">保存审查意见</button><span id="review-saved" class="subtle"></span>`}
function saveDecision(){decisions[activeReviewKey]={choice:$('review-choice').value,note:$('review-note').value,updated_at:new Date().toISOString()};localStorage.setItem('acedata-coze-review-20261005',JSON.stringify(decisions));$('review-saved').textContent=' 已保存在本机'}
$('export-review').onclick=()=>{const url=URL.createObjectURL(new Blob([JSON.stringify({catalog_date:'2026-10-05',publication_authorized:false,decisions},null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='coze-review-decisions.json';a.click();URL.revokeObjectURL(url)};
function open(title,icon,body){$('detailtop').innerHTML=`<img class="icon" src="${icon}" alt=""><h2>${esc(title)}</h2><button class="close" onclick="document.getElementById('detail').close()">关闭</button>`;$('detailbody').innerHTML=body+reviewForm(activeReviewKey);$('review-choice').value=decisions[activeReviewKey]?.choice||'pending';$('detail').showModal();}
function detail(key){activeReviewKey='service:'+key;const r=data.services.find(x=>x.key===key),l=r.listing;open(r.name||r.title,r.icon_data,`<h3>名称与简短介绍</h3><p><strong>${esc(r.name||r.title)}</strong>\n${esc(r.brief||r.description)}</p>${l?`<h3>完整上架文案</h3><p>${esc(l.about)}</p><h3>使用场景</h3><ul>${l.scenarios.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>拟选分类：${esc(l.category)}（提交时需核对商店可选分类）</p>`:`<h3>面向用户的入口</h3><p>${esc(r.description)}</p><p>通过 AceData Service Guide 引导用户到具体服务页，查看获取方式和所需配置。</p>`}<h3>当前状态与待验证项</h3>${r.draft&&r.draft.tools_imported===false?'<p><strong>仅项目信息已保存，工具导入未成功。</strong></p>':''}${r.draft&&r.draft.import_scope?`<p><strong>Coze 导入范围：</strong>${esc(r.draft.import_scope)}</p>`:''}${r.draft&&r.draft.final_icon_sync===false?'<p>最终图标和扩展定义尚未全部同步到 Coze。</p>':''}<div class="statusnote">${r.draft?`Coze 草稿已保存：<a href="${r.draft.url}" target="_blank">打开草稿</a>。当前新版 Coze 运行：${r.draft.real_trial?'已记录证据':'尚未验证'}${r.draft.initial_version_real_trial?'；初始版本曾有真实 Coze 成功证据，不能代替新版验证':''}`:'尚无完整新版 Coze 草稿验证记录。'}${r.plugin_url?`<br>初始版本：<a href="${r.plugin_url}" target="_blank">打开</a>`:''}</div><ul>${r.blockers.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>${r.starter?`<h3>最小测试请求 / 测试条件</h3><pre>${esc(JSON.stringify(r.starter,null,2))}</pre>`:''}${r.trial?`<h3>本次真实测试</h3><div class="statusnote">${esc(trialStatus[r.trial.status]||r.trial.status)}。执行来源：API 直接调用；尚未通过 Coze 运行验证。${r.trial.status==='media_url_verified'?'成品链接已通过可访问性检查，视听质量需单独审查。':r.trial.status==='media_url_needs_check'?'链接访问或播放未通过，暂不能按可用成品交付。':'以下为本次调用的实际状态与返回内容。'}</div>${r.trial.launch_blocker?`<p><strong>上线阻塞：</strong>${esc(r.trial.launch_blocker)}</p>`:''}${r.trial.assistant_text?`<p>${esc(r.trial.assistant_text)}</p>`:''}${r.trial.extracted_text?`<pre>${esc(r.trial.extracted_text)}</pre>`:''}${(r.trial.media||[]).filter(m=>m.http_status===200).map(m=>(m.content_type||'').includes('image')?`<img class="resultmedia" src="${esc(m.url)}" loading="lazy" alt="Real test result">`:(m.content_type||'').includes('audio')?`<audio controls preload="none" src="${esc(m.url)}"></audio>`:`<video class="resultmedia" controls preload="none" src="${esc(m.url)}"></video>`).join('')}<pre>${esc(JSON.stringify(r.trial.request,null,2))}</pre>`:''}<h3>接口覆盖</h3>${r.operations.length?`<table><thead><tr><th>方法与接口</th><th>准备状态</th><th>说明</th></tr></thead><tbody>${r.operations.map(o=>`<tr><td><span class="method">${esc(o.method)}</span> ${esc(o.path)}</td><td>${esc(o.disposition)}</td><td>${esc(o.reason||o.stage||'')}${o.docs?` <a href="${esc(o.docs)}" target="_blank">文档</a>`:''}</td></tr>`).join('')}</tbody></table>`:'<p>目录未声明独立 API，未虚构调用能力。</p>'}${l?`<h3>隐私声明准备</h3><pre>${esc(JSON.stringify(l.privacy_review,null,2))}</pre>`:''}<p><a href="${esc(r.source_url)}" target="_blank">打开官方服务页</a></p>`);}
$('apps').innerHTML=data.apps.map(a=>`<article class="app"><img src="${a.icon_data}" alt=""><h3>${esc(a.name)}</h3><p>${esc(a.description)}</p><p>${a.plugins?esc(a.plugins.join(' · ')):'覆盖全部 83 项服务的目录知识'}</p><p>${a.draft?`Coze 草稿已保存 · <a href="${esc(a.draft.url)}" target="_blank">打开 Agent ↗</a>`:'待在 Coze 建立草稿'}</p><button data-app="${a.id}">审查应用配置</button></article>`).join('');document.querySelectorAll('[data-app]').forEach(b=>b.onclick=()=>{let a=data.apps.find(x=>x.id===b.dataset.app);activeReviewKey='app:'+a.id;open(a.name,a.icon_data,`<div class="statusnote">${a.draft?`Coze Agent 草稿已保存：<a href="${esc(a.draft.url)}" target="_blank">打开草稿</a>。${a.draft.knowledge_bound?'目录知识已绑定，包含 84 个段落（83 项服务与目录说明）。已完成一次真实 Coze 导航测试，准确返回 Palmer Penguins 数据集链接及访问限制。':'工具绑定等待插件工作区发布；未通过完整运行验证。'}`:'配置已备好，尚未建立实际 Agent。'}正式发布等待用户审查。</div><h3>开场白</h3><p>${esc(a.opening_message)}</p><h3>示例提问</h3><ul>${a.suggested_prompts.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>完整配置</h3><pre>${esc(JSON.stringify(Object.fromEntries(Object.entries(a).filter(([k])=>k!=='icon_data'&&k!=='draft')),null,2))}</pre>`)});$('search').oninput=render;$('type').onchange=render;$('all').onclick=()=>{onlyNeeds=false;$('all').classList.add('active');$('needs').classList.remove('active');render()};$('needs').onclick=()=>{onlyNeeds=true;$('needs').classList.add('active');$('all').classList.remove('active');render()};render();</script></html>'''.replace('PAYLOAD',payload)
args.output.parent.mkdir(parents=True,exist_ok=True);args.output.write_text(html);print(args.output)
